import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M13.287 5.958a1 1 0 0 0-.574-1.916l-10 3c-.95.285-.95 1.631 0 1.916l10 3a1 1 0 0 0 .574-1.916L6.48 8z"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["m7.162 10 9.154 3.052a1 1 0 0 1-.632 1.897l-12-4c-.912-.304-.912-1.594 0-1.897l12-4a1 1 0 0 1 .632 1.897z"] as readonly string[];

export const LessThanIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="less-than" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
LessThanIcon.displayName = `Blueprint6.Icon.LessThanIcon`;

/**
 * @deprecated Use {@link LessThanIcon} instead.
 */
export const LessThan: typeof LessThanIcon = LessThanIcon;

export default LessThanIcon;
